'use strict'

import AbstractPanel from 'Panel/abstract-panel'
import event from '../event'
import { getSelectValue, setSelectValue } from '../form'
import { TILE_WIDTH, TILE_HEIGHT, MAP_TYPES, ENEMY_SPAWN_CLOUD } from '../../constant'
import resource from '../../resource'
import { Extra } from '../../model/extra'
import { Character } from '../../model/character'
import { Item } from '../../model/item'

const PREVIEW_WIDTH = 145
const PREVIEW_HEIGHT = 100

class MapPanel extends AbstractPanel {
  constructor (element, container, minWidth, minHeight, maxWidth, maxHeight) {
    super(element, container, minWidth, minHeight, maxWidth, maxHeight)

    // Preview
    this.canvas = element.querySelector('canvas')
    this.context = this.canvas.getContext('2d')
    this.canvas.width = PREVIEW_WIDTH
    this.canvas.height = PREVIEW_HEIGHT

    // Character
    this.addCharacterButton = element.querySelector('button#add-character')
    this.characterList = element.querySelector('div#character-list')
    this.characterSectionTemplate = this.characterList.querySelector('.character-section')
    this.characterSectionTemplate.remove()
    this.addCharacterButtonListener = this.addCharacterButtonListener.bind(this)

    // Items
    this.addItemButton = element.querySelector('button#add-item')
    this.itemList = element.querySelector('div#item-list')
    this.itemSectionTemplate = this.itemList.querySelector('.item-section')
    this.itemSectionTemplate.remove()
    this.addItemButtonListener = this.addItemButtonListener.bind(this)

    // Extras
    this.addExtraButton = element.querySelector('button#add-extra')
    this.extraList = element.querySelector('div#extra-list')
    this.extraSectionTemplate = this.extraList.querySelector('.extra-section')
    this.extraSectionTemplate.remove()
    this.addExtraButtonListener = this.addExtraButtonListener.bind(this)

    // Enemies
    this.addEnemyButton = element.querySelector('button#add-enemy')
    this.enemyList = element.querySelector('div#enemy-list')
    this.enemySectionTemplate = this.enemyList.querySelector('.enemy-section')
    this.enemySectionTemplate.remove()
    this.addEnemyButtonListener = this.addEnemyButtonListener.bind(this)
    this.enemySpawnSelect = element.querySelector('select[name="enemy-spawn-select"]')
    this.enemySpawnSelect.addEventListener('change', (e) => {
      e.preventDefault()
      if (this.map) {
        this.map.enemySpawn = getSelectValue(this.enemySpawnSelect)
        event.broadcast('map-panel:update')
      }
    })

    // What the cave does
    this.caveSelect = element.querySelector('select[name="cave-select"]')
    this.caveSelect.addEventListener('change', (e) => {
      e.preventDefault()
      if (this.map) {
        this.map.cave = getSelectValue(this.caveSelect) || undefined
        event.broadcast('map-panel:update')
      }
    })

    this.start()
    this.draw()
  }

  start () {
    const self = this

    event.on('world-panel:select-map', (map) => {
      self.canvas.closest('.panel-body').classList.remove('hidden')
      self.applyMap(map)
      self.draw()
    })
    event.on('editor:cancel', () => {
      self.canvas.closest('.panel-body').classList.add('hidden')
      self.applyMap()
      self.draw()
    })
    for (const type of MAP_TYPES) {
      event.on(`menu:map-selector:display-${type}`, () => {
        self.applyMap()
        self.draw()
      })
    }
  }

  reset () {
    this.element.querySelectorAll('.section').forEach((element) => {
      element.classList.add('hidden')
    })

    if (!this.map) {
      return
    }

    // Character
    this.addCharacterButton.removeEventListener('click', this.savedAddCharacterButtonListener)
    this.resetSections(this.characterList)

    // Items
    this.addItemButton.removeEventListener('click', this.savedAddItemButtonListener)
    this.resetSections(this.itemList)

    // Extras
    this.addExtraButton.removeEventListener('click', this.savedAddExtraButtonListener)
    this.resetSections(this.extraList)

    // Enemies
    this.addEnemyButton.removeEventListener('click', this.savedAddEnemyButtonListener)
    this.resetSections(this.enemyList)
  }

  applyMap (map) {
    this.reset()
    this.map = map
    if (!map) {
      return
    }

    this.element.querySelectorAll('.section').forEach((element) => {
      element.classList.remove('hidden')
    })

    // Character
    this.addCharacterButton.addEventListener('click', this.savedAddCharacterButtonListener = this.addCharacterButtonListener)
    this.initCharacters()
    this.toggleAddCharacterButtonEnabled()

    // Items
    this.addItemButton.addEventListener('click', this.savedAddItemButtonListener = this.addItemButtonListener)
    setSelectValue(this.caveSelect, map.cave ?? '')
    this.initItems()
    this.toggleAddItemButtonEnabled()

    // Extras
    this.addExtraButton.addEventListener('click', this.savedAddExtraButtonListener = this.addExtraButtonListener)
    this.initExtras()
    this.toggleAddExtraButtonEnabled()

    // Enemies
    this.addEnemyButton.addEventListener('click', this.savedAddEnemyButtonListener = this.addEnemyButtonListener)
    setSelectValue(this.enemySpawnSelect, map.enemySpawn ?? ENEMY_SPAWN_CLOUD)
    this.initEnemies()
    this.toggleAddEnemyButtonEnabled()
  }

  toggleAddCharacterButtonEnabled () {
    const max = this.addCharacterButton.dataset.max ? parseInt(this.addCharacterButton.dataset.max) : undefined
    if (max && this.characterList.children.length >= max) {
      this.addCharacterButton.setAttribute('disabled', true)
    } else {
      this.addCharacterButton.removeAttribute('disabled')
    }
  }

  addCharacterButtonListener (e) {
    e.preventDefault()
    this.addCharacterSection()
    this.toggleAddCharacterButtonEnabled()
  }

  addCharacterSection () {
    const section = this.characterSectionTemplate.cloneNode(true)
    const self = this
    section.querySelector('button[name="character-remove"]').addEventListener('click', (e) => {
      e.preventDefault()
      section.remove()
      self.updateCharacters(self.characterList)
      self.toggleAddCharacterButtonEnabled()
    })
    section.querySelector('select[name="character-select"]').addEventListener('change', (e) => {
      e.preventDefault()
      self.updateCharacters(self.characterList)
    })
    section.querySelector('input[name="character-column-input"]').addEventListener('change', (e) => {
      e.preventDefault()
      self.updateCharacters(self.characterList)
    })
    section.querySelector('input[name="character-line-input"]').addEventListener('change', (e) => {
      e.preventDefault()
      self.updateCharacters(self.characterList)
    })
    section.querySelector('input[name="character-text-input"]').addEventListener('change', (e) => {
      e.preventDefault()
      self.updateCharacters(self.characterList)
    })
    this.characterList.appendChild(section)
    return section
  }

  initCharacters () {
    for (const character of this.map.characters) {
      const section = this.addCharacterSection()
      setSelectValue(section.querySelector('select[name="character-select"]'), character.sprite.name)
      section.querySelector('input[name="character-column-input"]').value = character.column
      section.querySelector('input[name="character-line-input"]').value = character.line
      section.querySelector('input[name="character-text-input"]').value = character.text ?? ''
    }
  }

  updateCharacters (container) {
    this.map.characters = []
    container.querySelectorAll('.character-section').forEach((section) => {
      const spriteName = getSelectValue(section.querySelector('select[name="character-select"]'))
      const sprite = resource.getSprite(spriteName)
      const name = spriteName.replace('misc_', '')
      const column = section.querySelector('input[name="character-column-input"]').value ? parseFloat(section.querySelector('input[name="character-column-input"]').value) : undefined
      const line = section.querySelector('input[name="character-line-input"]').value ? parseFloat(section.querySelector('input[name="character-line-input"]').value) : undefined
      const text = section.querySelector('input[name="character-text-input"]').value ?? ''
      if (!!sprite && column !== undefined && line !== undefined) {
        const x = this.map.x + TILE_WIDTH * column
        const y = this.map.y + TILE_HEIGHT * line
        const character = new Character(name, column, line, x, y, TILE_WIDTH, TILE_HEIGHT, sprite, text)
        this.map.characters.push(character)
      }
    })
    this.draw()
    event.broadcast('map-panel:update')
  }

  toggleAddItemButtonEnabled () {
    const max = this.addItemButton.dataset.max ? parseInt(this.addItemButton.dataset.max) : undefined
    if (max && this.itemList.children.length >= max) {
      this.addItemButton.setAttribute('disabled', true)
    } else {
      this.addItemButton.removeAttribute('disabled')
    }
  }

  addItemButtonListener (e) {
    e.preventDefault()
    this.addItemSection()
    this.toggleAddItemButtonEnabled()
  }

  addItemSection () {
    const section = this.itemSectionTemplate.cloneNode(true)
    const self = this
    section.querySelector('button[name="item-remove"]').addEventListener('click', (e) => {
      e.preventDefault()
      section.remove()
      self.updateItems(self.itemList)
      self.toggleAddItemButtonEnabled()
    })
    section.querySelector('select[name="item-select"]').addEventListener('change', (e) => {
      e.preventDefault()
      self.updateItems(self.itemList)
    })
    section.querySelector('input[name="item-column-input"]').addEventListener('change', (e) => {
      e.preventDefault()
      self.updateItems(self.itemList)
    })
    section.querySelector('input[name="item-line-input"]').addEventListener('change', (e) => {
      e.preventDefault()
      self.updateItems(self.itemList)
    })
    section.querySelector('input[name="item-price-input"]').addEventListener('change', (e) => {
      e.preventDefault()
      self.updateItems(self.itemList)
    })
    this.itemList.appendChild(section)
    return section
  }

  initItems () {
    for (const item of this.map.items) {
      const section = this.addItemSection()
      setSelectValue(section.querySelector('select[name="item-select"]'), item.sprite.name)
      section.querySelector('input[name="item-column-input"]').value = item.column
      section.querySelector('input[name="item-line-input"]').value = item.line
      section.querySelector('input[name="item-price-input"]').value = item.price
    }
  }

  updateItems (container) {
    // What the form does not show (answer of a pay_to_talk cave, rupees of a secret) stays with the item
    const previousItems = this.map.items
    this.map.items = []
    container.querySelectorAll('.item-section').forEach((section, index) => {
      const spriteName = getSelectValue(section.querySelector('select[name="item-select"]'))
      const sprite = resource.getSprite(spriteName)
      const name = spriteName.replace('item_', '')
      const column = section.querySelector('input[name="item-column-input"]').value ? parseFloat(section.querySelector('input[name="item-column-input"]').value) : undefined
      const line = section.querySelector('input[name="item-line-input"]').value ? parseFloat(section.querySelector('input[name="item-line-input"]').value) : undefined
      const price = section.querySelector('input[name="item-price-input"]').value ? parseInt(section.querySelector('input[name="item-price-input"]').value) : undefined
      if (!!sprite && column !== undefined && line !== undefined) {
        const x = this.map.x + TILE_WIDTH * column
        const y = this.map.y + TILE_HEIGHT * line
        const previous = previousItems[index]?.name === name ? previousItems[index] : undefined
        const item = new Item(name, column, line, x, y, TILE_WIDTH, TILE_HEIGHT, sprite, price, { text: previous?.text, rupees: previous?.rupees })
        this.map.items.push(item)
      }
    })
    this.draw()
    event.broadcast('map-panel:update')
  }

  toggleAddExtraButtonEnabled () {
    const max = this.addExtraButton.dataset.max ? parseInt(this.addExtraButton.dataset.max) : undefined
    if (max && this.extraList.childNodes.length >= max) {
      this.addExtraButton.setAttribute('disabled', true)
    } else {
      this.addExtraButton.removeAttribute('disabled')
    }
  }

  addExtraButtonListener (e) {
    e.preventDefault()
    this.addExtraSection()
    this.toggleAddExtraButtonEnabled()
  }

  addExtraSection () {
    const section = this.extraSectionTemplate.cloneNode(true)
    const self = this
    section.querySelector('button[name="extra-remove"]').addEventListener('click', (e) => {
      e.preventDefault()
      section.remove()
      self.updateExtras(self.extraList)
      self.toggleAddExtraButtonEnabled()
    })
    section.querySelector('select[name="extra-select"]').addEventListener('change', (e) => {
      e.preventDefault()
      self.updateExtras(self.extraList)
    })
    section.querySelector('input[name="extra-column-input"]').addEventListener('change', (e) => {
      e.preventDefault()
      self.updateExtras(self.extraList)
    })
    section.querySelector('input[name="extra-line-input"]').addEventListener('change', (e) => {
      e.preventDefault()
      self.updateExtras(self.extraList)
    })
    this.extraList.appendChild(section)
    return section
  }

  resetSections (container) {
    container.replaceChildren()
  }

  initExtras () {
    for (const extra of this.map.extras) {
      const section = this.addExtraSection()
      setSelectValue(section.querySelector('select[name="extra-select"]'), extra.sprite.name)
      section.querySelector('input[name="extra-column-input"]').value = extra.column
      section.querySelector('input[name="extra-line-input"]').value = extra.line
    }
  }

  updateExtras (container) {
    this.map.extras = []
    container.querySelectorAll('.extra-section').forEach((section) => {
      const sprite = resource.getSprite(getSelectValue(section.querySelector('select[name="extra-select"]')))
      const column = section.querySelector('input[name="extra-column-input"]').value ? parseFloat(section.querySelector('input[name="extra-column-input"]').value) : undefined
      const line = section.querySelector('input[name="extra-line-input"]').value ? parseFloat(section.querySelector('input[name="extra-line-input"]').value) : undefined
      if (!!sprite && column !== undefined && line !== undefined) {
        const x = this.map.x + TILE_WIDTH * column
        const y = this.map.y + TILE_HEIGHT * line
        const extra = new Extra(column, line, x, y, TILE_WIDTH, TILE_HEIGHT, sprite)
        this.map.extras.push(extra)
      }
    })
    this.draw()
    event.broadcast('map-panel:update')
  }

  toggleAddEnemyButtonEnabled () {
    const max = this.addEnemyButton.dataset.max ? parseInt(this.addEnemyButton.dataset.max) : undefined
    if (max && this.enemyList.children.length >= max) {
      this.addEnemyButton.setAttribute('disabled', true)
    } else {
      this.addEnemyButton.removeAttribute('disabled')
    }
  }

  addEnemyButtonListener (e) {
    e.preventDefault()
    this.addEnemySection()
    this.toggleAddEnemyButtonEnabled()
  }

  addEnemySection () {
    const section = this.enemySectionTemplate.cloneNode(true)
    const self = this
    section.querySelector('button[name="enemy-remove"]').addEventListener('click', (e) => {
      e.preventDefault()
      section.remove()
      self.updateEnemies(self.enemyList)
      self.toggleAddEnemyButtonEnabled()
    })
    section.querySelector('select[name="enemy-select"]').addEventListener('change', (e) => {
      e.preventDefault()
      self.updateEnemies(self.enemyList)
    })
    section.querySelector('input[name="enemy-count-input"]').addEventListener('change', (e) => {
      e.preventDefault()
      self.updateEnemies(self.enemyList)
    })
    this.enemyList.appendChild(section)
    return section
  }

  initEnemies () {
    for (const enemy of this.map.enemies) {
      const section = this.addEnemySection()
      setSelectValue(section.querySelector('select[name="enemy-select"]'), enemy.type)
      section.querySelector('input[name="enemy-count-input"]').value = enemy.count
    }
  }

  // Only the definition is kept: the enemies themselves only appear in the game
  updateEnemies (container) {
    this.map.enemies = []
    container.querySelectorAll('.enemy-section').forEach((section) => {
      const type = getSelectValue(section.querySelector('select[name="enemy-select"]'))
      const count = parseInt(section.querySelector('input[name="enemy-count-input"]').value)
      if (type && count > 0) {
        this.map.enemies.push({ type, count })
      }
    })
    event.broadcast('map-panel:update')
  }

  draw () {
    this.context.fillStyle = this.color
    this.context.fillRect(0, 0, this.canvas.width, this.canvas.height)

    if (this.map) {
      this.context.save()

      this.context.scale(PREVIEW_WIDTH / this.map.width, PREVIEW_HEIGHT / this.map.height)
      this.context.translate(-this.map.x, -this.map.y)
      this.map.draw(this.context)
      this.context.restore()
    }
  }

  resizePanel (element, event) {
    super.resizePanel(element, event)
    this.canvas.width = PREVIEW_WIDTH
    this.canvas.height = PREVIEW_HEIGHT
  }
}

export { MapPanel }
